WITH latest AS (SELECT id, account_id, txn_type, amount, txn_time FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY txn_type ORDER BY amount DESC, id) AS row_num FROM transactions) ranked WHERE row_num = 1) SELECT s.id, s.account_id, s.txn_type, s.amount, s.txn_time, CASE WHEN txn_type RLIKE '^(CREDIT|DEBIT)$' THEN 'PRIORITY' WHEN txn_type RLIKE '^(REFUND|FEE)$' THEN 'EXTENDED' ELSE 'CORE' END AS txn_type_zone, (SELECT AVG(t2.amount) FROM transactions t2 WHERE t2.account_id = s.account_id) AS avg_transaction_amount FROM latest s
